function bodyKey(b){if(b.type==='Entity')return `<div class="orbit-key entity-key ${selectedWorld===b.name?'selected':''}" style="--body-color:${b.tint}"><button data-world="${esc(b.name)}" aria-label="Inspect ${esc(planetLabel(b.name))}">✧</button><div class="object-key-name">${link(b.name)}<small>${esc(b.tag)} · slow stellar orbit</small></div></div>`;const station=b.type==='Station',label=station?b.code:b.type==='Moon'?'M':b.layoutSlot||'◇';
 return `<div class="orbit-key ${!['World','Moon'].includes(b.type)?'site ':''}${selectedWorld===b.name?'selected':''}" style="--body-color:${b.tint}"><button data-world="${esc(b.name)}" ${b.category==='TORA'?'data-tora=""':''} aria-label="Inspect ${esc(planetLabel(b.name))}">${label}</button><div class="object-key-name">${link(b.name,b.name,b.category==='TORA'?'tora-register-link':'')}${station?`<small>${esc(b.categoryUnspecified?'Other · category unknown':b.category)} · ${esc(b.status||'operational')}</small>`:''}${b.category==='TORA'?`<button class="tora-link" data-tora-open="${esc(b.name)}">Station overview ↗</button>`:''}</div>${!station?`<small>${b.type==='Moon'?'moon of '+link(b.parent):b.slot?'orbit '+String(b.slot).padStart(2,'0'):b.type==='World'?'orbit unspecified':b.type==='Colony'?'colony':'site'}</small>`:''}</div>`;
}
